  `referrer_user_id` bigint(20) NOT NULL COMMENT '推荐人用户ID（wo_user.id）',
  `amount` decimal(10, 2) NOT NULL COMMENT '佣金金额',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING-待结算 / SETTLED-已结算（账面认定，未发钱） / PAID-已发放（管理员线下转账后回填留痕） / CANCELLED-已取消（PENDING 阶段退款/虚假推荐/人工取消，终态） / DEDUCTED-已扣除（SETTLED/PAID 后退款/人工扣除，账面调整不发起任何资金动作，终态）',
  `settle_time` datetime NULL DEFAULT NULL COMMENT '结算时间',
  `deduct_reason` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '扣除原因（退款等）',
  `paid_time` datetime NULL DEFAULT NULL COMMENT '线下发放时间（管理员手工回填）',
  `paid_channel` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '线下发放渠道：alipay-transfer/wechat-redpack/bank-transfer/offline-other',
  `paid_tx_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '线下发放外部流水号（管理员手工填，便于审计）',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注、调整原因等',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_id`(`order_id`) USING BTREE COMMENT '一单一佣',
  INDEX `idx_referrer_user_id`(`referrer_user_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_create_time`(`create_time`) USING BTREE,
  INDEX `idx_paid_time`(`paid_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '佣金记录表(会员营销)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of store_commission
-- ----------------------------

-- ----------------------------
-- Table structure for store_license
-- ----------------------------
DROP TABLE IF EXISTS `store_license`;
CREATE TABLE `store_license`  (
  `id` bigint(20) UNSIGNED NOT NULL,
  `order_id` bigint(20) NOT NULL COMMENT '订单ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单号',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `com_id` bigint(20) NULL DEFAULT 0 COMMENT '租户公司',
  `plugin_id` bigint(20) NOT NULL COMMENT '插件ID',
  `plugin_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '插件编码',
  `license_key` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'License字符串（签名结果）',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '过期时间',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE/EXPIRED/REVOKED',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_id`(`order_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_plugin_id`(`plugin_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'License记录表(商业模块)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of store_license
-- ----------------------------

-- ----------------------------
-- Table structure for store_marketing_rule
-- ----------------------------
DROP TABLE IF EXISTS `store_marketing_rule`;
CREATE TABLE `store_marketing_rule`  (
  `id` bigint(20) UNSIGNED NOT NULL,
  `rule_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DEFAULT' COMMENT '规则编码，如 DEFAULT',
  `commission_rate` decimal(5, 4) NULL DEFAULT NULL COMMENT '佣金比例，如 0.0500 表示 5%',
  `discount_rate` decimal(5, 4) NULL DEFAULT NULL COMMENT '新用户优惠比例，如 0.1000 表示 10%',
  `discount_amount_max` decimal(10, 2) NULL DEFAULT NULL COMMENT '单笔优惠金额上限（元）',
  `is_enabled` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '是否启用：0否 1是',
  `create_time` datetime NOT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `remark` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_rule_code`(`rule_code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '推荐营销规则表(会员营销)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of store_marketing_rule
-- ----------------------------

-- ----------------------------
-- Table structure for store_order
-- ----------------------------
DROP TABLE IF EXISTS `store_order`;
CREATE TABLE `store_order`  (
  `id` bigint(20) UNSIGNED NOT NULL,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单号',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `com_id` bigint(20) NULL DEFAULT 0 COMMENT '租户公司',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '渠道组织',
  `total_amount` decimal(10, 2) NOT NULL COMMENT '订单总金额',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING/PAID/COMPLETED/CLOSED/REFUNDED/ABNORMAL',
  `product_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PLUGIN' COMMENT 'PLUGIN/SCENARIO',
  `product_id` bigint(20) NULL DEFAULT NULL COMMENT '插件或产品ID',
  `product_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '插件code或产品标识',
  `product_version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `pay_channel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'WECHAT/ALIPAY',
  `pay_time` datetime NULL DEFAULT NULL,
  `transaction_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `close_time` datetime NULL DEFAULT NULL,
  `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT NULL,
  `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'normal',
  `is_valid` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1',
  `versions` int(10) NULL DEFAULT NULL COMMENT '乐观锁',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `referral_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '下单时填写的推荐码',
  `referrer_user_id` bigint(20) NULL DEFAULT NULL COMMENT '推荐人用户ID（platform wo_user.id）',
  `discount_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '推荐码抵扣金额（优惠金额）',
  `commission_id` bigint(20) NULL DEFAULT NULL COMMENT '佣金记录ID，关联 store_commission.id',
  `commission_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '佣金计算状态：PENDING/SETTLED/DEDUCTED/CANCELLED/NONE',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_no`(`order_no`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_create_time`(`create_time`) USING BTREE,
  INDEX `idx_product`(`product_type`, `product_id`) USING BTREE,
  INDEX `idx_referrer`(`referrer_user_id`) USING BTREE,
  INDEX `idx_commission_id`(`commission_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '订单表(商业模块)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of store_order
-- ----------------------------

-- ----------------------------
-- Table structure for store_payment
-- ----------------------------
DROP TABLE IF EXISTS `store_payment`;
CREATE TABLE `store_payment`  (
  `id` bigint(20) UNSIGNED NOT NULL,
  `order_id` bigint(20) NOT NULL COMMENT '订单ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单号',
  `pay_channel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'WECHAT/ALIPAY',
  `transaction_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '支付渠道交易号',
  `amount` decimal(10, 2) NOT NULL COMMENT '支付金额',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT 'SUCCESS/FAIL/PENDING',
  `notify_time` datetime NULL DEFAULT NULL COMMENT '回调时间',
  `raw_notify` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '原始回调内容(对账用)',
  `create_time` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_transaction`(`pay_channel`, `transaction_id`) USING BTREE,
  INDEX `idx_order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '支付记录表(商业模块)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of store_payment
-- ----------------------------

-- ----------------------------
-- Table structure for store_plugin
-- ----------------------------
DROP TABLE IF EXISTS `store_plugin`;
CREATE TABLE `store_plugin`  (
                                 `id` bigint(20) NOT NULL,
                                 `plugin_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `plugin_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                                 `version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `description` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `install_info` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `version_history` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `preview_pic` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `plugin_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `down_count` bigint(20) NULL DEFAULT NULL ,
                                 `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `author` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `main_class` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `star_count` bigint(20) NULL DEFAULT NULL ,
                                 `like_count` bigint(20) NULL DEFAULT NULL ,
                                 `review_count` bigint(20) NULL DEFAULT NULL ,
                                 `review_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `review_message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `review_by` bigint(20) NULL DEFAULT NULL ,
                                 `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' ,
                                 `display_order` int(10) NULL DEFAULT NULL ,
                                 `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                 `create_time` datetime NULL DEFAULT NULL ,
                                 `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                                 `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                 `update_time` datetime NULL DEFAULT NULL ,
                                 `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                                 `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `versions` int(10) NULL DEFAULT NULL ,
                                 `repo_branch` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `repo_commit` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `repo_last_update` datetime NULL DEFAULT NULL ,
                                 `install_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'UPLOAD' ,
                                 `auto_update` tinyint(1) NULL DEFAULT 0 ,
                                 PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of store_plugin
-- ----------------------------

-- ----------------------------
-- Table structure for wo_account_association
-- ----------------------------
DROP TABLE IF EXISTS `wo_account_association`;
CREATE TABLE `wo_account_association`  (
                                           `id` bigint(20) UNSIGNED NOT NULL,
                                           `user_id` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                           `bind_account` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                           `third_domain` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                           `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                           `create_time` datetime NULL DEFAULT NULL ,
                                           `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                                           `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                           `update_time` datetime NULL DEFAULT NULL ,
                                           `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                                           `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                           `versions` int(10) NULL DEFAULT NULL ,
                                           PRIMARY KEY (`id`) USING BTREE,
                                           INDEX `idx_user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '账号关联表：与账号表结合定义了账号关系链，保证第三方方式登录时可以通过链认证用户。用户登录后，还可以选择绑定多个第三方账' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wo_account_association
-- ----------------------------

-- ----------------------------
-- Table structure for wo_app
-- ----------------------------
DROP TABLE IF EXISTS `wo_app`;
CREATE TABLE `wo_app`  (
                           `id` bigint(20) UNSIGNED NOT NULL ,
                           `app_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                           `app_secret` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                           `app_code` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                           `app_desc` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                           `app_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                           `app_origin` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'internal' ,
                           `com_id` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                           `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                           `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                           `create_time` datetime NULL DEFAULT NULL ,
                           `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                           `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                           `update_time` datetime NULL DEFAULT NULL ,
                           `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                           `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                           `versions` int(10) NULL DEFAULT NULL ,
                           PRIMARY KEY (`id`) USING BTREE,
                           UNIQUE INDEX `app_code`(`app_code`) USING BTREE,
                           INDEX `app_type`(`app_type`) USING BTREE,
                           INDEX `app_com_id`(`com_id`) USING BTREE,
                           INDEX `app_is_valid_del`(`is_valid`, `delete_flag`) USING BTREE,
                           INDEX `idx_app_origin`(`app_origin`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '应用定义表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wo_app
-- ----------------------------

-- ----------------------------
-- Table structure for wo_architecture
-- ----------------------------
DROP TABLE IF EXISTS `wo_architecture`;
CREATE TABLE `wo_architecture`  (
                                    `id` bigint(20) UNSIGNED NOT NULL ,
                                    `arch_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                    `arch_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                    `arch_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                    `com_id` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                    `parent_id` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                    `display_order` int(10) NULL DEFAULT NULL ,
                                    `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                    `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                    `create_time` datetime NULL DEFAULT NULL ,
                                    `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                                    `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                    `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                                    `update_time` datetime NULL DEFAULT NULL ,
                                    `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                    `versions` int(10) NULL DEFAULT NULL ,
                                    PRIMARY KEY (`id`) USING BTREE,
                                    UNIQUE INDEX `un_com_arch`(`arch_code`, `com_id`) USING BTREE,
                                    INDEX `arch_code`(`arch_code`) USING BTREE,
                                    INDEX `arch_com_id`(`com_id`) USING BTREE,
                                    INDEX `arch_parent_id`(`parent_id`) USING BTREE,
                                    INDEX `arch_is_valid_del`(`is_valid`, `delete_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '体系结构定义表（体系类型定义）：同一个公司，同一个体系结构内只能有一套组织机构，即一棵组织树，比如一套人事组织，一套工会，体系结构定义了某类组织的结构，如人事组织是由机构、部门、岗位和下面人员构成的，再比如群组一般由群主、管理员、组员构成。' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wo_architecture
-- ----------------------------

-- ----------------------------
-- Table structure for wo_auth_role
-- ----------------------------
DROP TABLE IF EXISTS `wo_auth_role`;
CREATE TABLE `wo_auth_role`  (
                                 `id` bigint(20) UNSIGNED NOT NULL ,
                                 `role_id` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                 `resource_id` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                 `app_id` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                 `domain_id` bigint(20) UNSIGNED NULL DEFAULT NULL COMMENT 'NULL=平台基线授权；非空=站点 overlay' ,
                                 `com_id` bigint(20) UNSIGNED NULL DEFAULT NULL COMMENT 'NULL=平台基线；非空=租户 overlay' ,
                                 `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                 `create_time` datetime NULL DEFAULT NULL ,
                                 `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                                 `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                 `update_time` datetime NULL DEFAULT NULL ,
                                 `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                                 `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                 `versions` int(10) NULL DEFAULT NULL ,
                                 PRIMARY KEY (`id`) USING BTREE,
                                 INDEX `auth_role_id`(`role_id`) USING BTREE,
                                 INDEX `auth_res_id`(`resource_id`) USING BTREE,
                                 INDEX `auth_app_id`(`app_id`) USING BTREE,
                                 INDEX `auth_is_valid_del`(`is_valid`, `delete_flag`) USING BTREE,
                                 INDEX `idx_auth_role_domain`(`role_id`, `domain_id`, `delete_flag`, `is_valid`) USING BTREE,
                                 INDEX `auth_role_res_app`(`role_id`, `resource_id`, `app_id`) USING BTREE,
                                 INDEX `idx_auth_role_com`(`role_id`, `com_id`, `domain_id`, `delete_flag`, `is_valid`) USING BTREE,
                                 INDEX `idx_auth_res_app_alive`(`resource_id`, `app_id`, `delete_flag`, `is_valid`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '权限定义表：定义组织机构下、角色或用户与资源的关系。权限所有者可以是若干个指定的用户、可以是若干个指定的组织机构、还可以' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wo_auth_role
-- ----------------------------


-- ----------------------------
-- Table structure for wo_com_user
-- ----------------------------
DROP TABLE IF EXISTS `wo_com_user`;
CREATE TABLE `wo_com_user`  (
                                `id` bigint(20) UNSIGNED NOT NULL ,
                                `user_id` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                `com_id` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                `is_main` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                `create_time` datetime NULL DEFAULT NULL ,
                                `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                                `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                `update_time` datetime NULL DEFAULT NULL ,
                                `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                                `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                `versions` int(10) NULL DEFAULT NULL ,
                                PRIMARY KEY (`id`) USING BTREE,
                                INDEX `com_user_id`(`user_id`) USING BTREE,
                                INDEX `com_id`(`com_id`) USING BTREE,
                                INDEX `com_is_main`(`is_main`) USING BTREE,
                                INDEX `com_is_valid_del`(`is_valid`, `delete_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '一个用户可以拥有或者归属多个公司，但同一时刻只能有一个主企业。在一个公司可以拥有多个角色，可以分属一个公司内多个体系结构下的组织。' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wo_com_user
-- ----------------------------

-- ----------------------------
-- Table structure for wo_company
-- ----------------------------
DROP TABLE IF EXISTS `wo_company`;
CREATE TABLE `wo_company`  (
                               `id` bigint(20) UNSIGNED NOT NULL ,
                               `com_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                               `com_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                               `com_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                               `parent_id` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                               `display_order` int(10) NULL DEFAULT NULL ,
                               `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                               `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                               `create_time` datetime NULL DEFAULT NULL ,
                               `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                               `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                               `update_time` datetime NULL DEFAULT NULL ,
                               `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                               `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                               `versions` int(10) NULL DEFAULT NULL ,
                               PRIMARY KEY (`id`) USING BTREE,
                               UNIQUE INDEX `un_com_code`(`com_code`) USING BTREE,
                               INDEX `com_parent_id`(`parent_id`) USING BTREE,
                               INDEX `com_is_valid_del`(`is_valid`, `delete_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '运营公司定义表：在云平台上使用容器化技术实现与多租户等效的行为表现，每个公司都有完整的应用管理和用户管理，其中顶层管理可' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wo_company
-- ----------------------------

-- ----------------------------
-- Table structure for wo_domain
-- ----------------------------
DROP TABLE IF EXISTS `wo_domain`;
CREATE TABLE `wo_domain`  (
                              `id` bigint(20) UNSIGNED NOT NULL ,
                              `com_id` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                              `site_domain` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                              `second_domain` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL ,
                              `site_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                              `site_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                              `site_logo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL ,
                              `favicon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL ,
                              `site_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL ,
                              `site_keyword` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL ,
                              `site_description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL ,
                              `slogan` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL ,
                              `foot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL ,
                              `flink` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL ,
                              `copy` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL ,
                              `portal_qr_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '页脚二维码外链（社区/客服等）',
                              `portal_footer_i18n` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '页脚多语言 JSON',
                              `admin_home_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '管理端首页 JSON',
                              `parent_id` bigint(20) NULL DEFAULT NULL ,
                              `display_order` int(10) NULL DEFAULT NULL ,
                              `cname_domain` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL ,
                              `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                              `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                              `create_time` datetime NULL DEFAULT NULL ,
                              `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                              `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                              `update_time` datetime NULL DEFAULT NULL ,
                              `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                              `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                              `versions` int(10) NULL DEFAULT NULL ,
                              PRIMARY KEY (`id`) USING BTREE,
                              UNIQUE INDEX `uni_idx_site_domain`(`site_domain`) USING BTREE,
                              UNIQUE INDEX `uni_second_dom`(`second_domain`) USING BTREE,
                              INDEX `domain_com_id`(`com_id`) USING BTREE,
                              INDEX `dom_is_valid_del`(`is_valid`, `delete_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '定义租户的站点或者域信息，域名、网址等信息，一个租户可以开通多个站点（一个顶级域或多个顶级域），可以配置不同站点上呈现的' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wo_domain
-- ----------------------------

-- ----------------------------
-- Table structure for wo_domain_admin
-- ----------------------------
DROP TABLE IF EXISTS `wo_domain_admin`;
CREATE TABLE `wo_domain_admin`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `domain_id` bigint(20) NOT NULL COMMENT '站点域',
  `user_id` bigint(20) NOT NULL COMMENT '管理员用户',
  `com_id` bigint(20) NULL DEFAULT 0 COMMENT '租户公司',
  `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1',
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT NULL,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `delete_flag` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'normal',
  `versions` int(11) NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_domain_user`(`domain_id`, `user_id`, `delete_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '域级管理员绑定' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wo_platform_admin
-- ----------------------------
DROP TABLE IF EXISTS `wo_platform_admin`;
CREATE TABLE `wo_platform_admin`  (
  `id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED NOT NULL,
  `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT NULL,
  `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
  `versions` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user`(`user_id`, `delete_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '平台超管登记册：平台超级管理员身份权威判据，admin 身份组仅作权限容器' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wo_tenant_admin
-- ----------------------------
DROP TABLE IF EXISTS `wo_tenant_admin`;
CREATE TABLE `wo_tenant_admin`  (
  `id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED NOT NULL,
  `com_id` bigint(20) UNSIGNED NOT NULL COMMENT '受托租户id',
  `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT NULL,
  `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
