  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tenant_user`(`com_id`, `user_id`, `delete_flag`) USING BTREE,
  INDEX `idx_user`(`user_id`, `delete_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '租户管理员登记册：租户管理员身份权威判据，tadmin 身份组仅作权限容器' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wo_trust_man
-- ----------------------------
DROP TABLE IF EXISTS `wo_trust_man`;
CREATE TABLE `wo_trust_man`  (
  `id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED NOT NULL,
  `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT NULL,
  `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
  `versions` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user`(`user_id`, `delete_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '守信人登记册：可信会员身份权威判据（平台级），can_trust 身份组仅作权限容器' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wo_slot_binding
-- ----------------------------
DROP TABLE IF EXISTS `wo_slot_binding`;
CREATE TABLE `wo_slot_binding`  (
  `id` bigint(20) UNSIGNED NOT NULL,
  `slot_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '插槽编码（BusinessSlot.slotCode）',
  `com_id` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '辖区租户id（0=平台）',
  `domain_id` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '站点id（0=租户级绑定）',
  `target_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标类型：role/org',
  `target_id` bigint(20) UNSIGNED NOT NULL COMMENT '绑定目标（wo_org/wo_role 主键）',
  `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT NULL,
  `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
  `versions` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_slot_scope`(`slot_code`, `com_id`, `domain_id`, `delete_flag`) USING BTREE,
  INDEX `idx_com`(`com_id`, `delete_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '插槽绑定：业务插槽绑定到租户/站点自建分群或角色，未绑定按插槽默认 Kind 解析' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wo_role_binding
-- ----------------------------
DROP TABLE IF EXISTS `wo_role_binding`;
CREATE TABLE `wo_role_binding`  (
  `id` bigint(20) UNSIGNED NOT NULL,
  `role_id` bigint(20) UNSIGNED NOT NULL COMMENT '角色id（wo_role.id）',
  `target_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标类型：user/org/identity/subject_type',
  `target_id` bigint(20) UNSIGNED NOT NULL COMMENT '绑定目标：userId/orgId/身份组wo_org.id/subjectTypeId',
  `com_id` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '辖区租户id（0=平台）',
  `domain_id` bigint(20) UNSIGNED NULL DEFAULT NULL COMMENT '站点id（null=租户级）',
  `arch_id` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '体系id：org 通道兼容键，其余通道恒 0',
  `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT NULL,
  `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
  `versions` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_target`(`target_type`, `target_id`, `delete_flag`, `is_valid`) USING BTREE,
  INDEX `idx_role`(`role_id`, `delete_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '多态角色绑定：人/组织/身份登记册/主体类型挂角色的统一绑定层（通道 C）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wo_domain_admin
-- ----------------------------

