                                  INDEX `dom_is_valid_del`(`is_valid`, `delete_flag`) USING BTREE,
                                  INDEX `dom_app_com`(`app_id`, `domain_id`, `com_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

