-- ----------------------------
-- Table structure for wo_domain_content_map
-- ----------------------------
DROP TABLE IF EXISTS `wo_domain_content_map`;
CREATE TABLE `wo_domain_content_map`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `source_domain_id` bigint(20) NOT NULL COMMENT '源域 ID',
  `source_pub_id` bigint(20) NOT NULL COMMENT '源正式行 pub_id',
  `target_domain_id` bigint(20) NOT NULL COMMENT '目标域 ID',
  `target_pub_id` bigint(20) NOT NULL COMMENT '目标正式行 pub_id',
  `map_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'clone' COMMENT 'clone / translation',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pair`(`source_domain_id`, `source_pub_id`, `target_domain_id`) USING BTREE,
  INDEX `idx_source`(`source_domain_id`, `source_pub_id`) USING BTREE,
  INDEX `idx_target`(`target_domain_id`, `target_pub_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '子站复制内容映射' ROW_FORMAT = Dynamic;

