-- Records of wo_domain_content_map
-- ----------------------------

-- ----------------------------
-- Table structure for wo_domain_option
-- ----------------------------
DROP TABLE IF EXISTS `wo_domain_option`;
CREATE TABLE `wo_domain_option`  (
  `id` bigint(20) UNSIGNED NOT NULL,
  `domain_id` bigint(20) UNSIGNED NOT NULL COMMENT 'wo_domain.id，访问域',
  `com_id` bigint(20) UNSIGNED NOT NULL COMMENT '租户公司，与列表隔离一致',
  `option_key` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `option_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `option_value` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `option_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'auto_reload',
  `app_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'sys_option',
  `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT NULL,
  `create_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `update_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'normal',
  `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1',
  `versions` int(11) NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_domain_option`(`domain_id`, `option_key`) USING BTREE,
  INDEX `idx_domain_option_com`(`com_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '域级系统选项' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wo_domain_option
-- ----------------------------

-- ----------------------------
-- Table structure for wo_domain_resource
-- ----------------------------
DROP TABLE IF EXISTS `wo_domain_resource`;
CREATE TABLE `wo_domain_resource`  (
                                       `id` bigint(20) NOT NULL,
                                       `module_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'static' ,
                                       `resource_id` bigint(20) UNSIGNED NOT NULL ,
                                       `app_id` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                       `term_type_id` bigint(20) NULL DEFAULT 0 ,
                                       `url` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                       `extra_props` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '域资源扩展JSON，下发DynSet.extraProps，如门户static见 portalStatic' ,
                                       `overlay_parent_id` bigint(20) UNSIGNED NULL DEFAULT NULL COMMENT '本站侧栏父节点 wo_resource.id；NULL继承parent_id' ,
                                       `overlay_display_order` int(11) NULL DEFAULT NULL COMMENT '本站排序；NULL继承display_order' ,
                                       `overlay_label` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '本站展示名；NULL继承resource_name' ,
                                       `domain_id` bigint(20) UNSIGNED NOT NULL ,
                                       `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                       `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                       `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                       `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                                       `create_time` datetime NULL DEFAULT NULL ,
                                       `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL ,
                                       `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
                                       `update_time` datetime NULL DEFAULT NULL ,
                                       `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL ,
                                       `versions` int(10) UNSIGNED NULL DEFAULT NULL ,
                                       PRIMARY KEY (`id`) USING BTREE,
                                       UNIQUE INDEX `dom_res_route`(`domain_id`, `resource_id`) USING BTREE,
                                       INDEX `dom_res_valid`(`is_valid`, `delete_flag`) USING BTREE,
                                       INDEX `dom_res_app`(`domain_id`, `app_id`, `resource_id`) USING BTREE,
                                       INDEX `dom_res_module`(`module_name`) USING BTREE,
                                       INDEX `dom_res_did`(`domain_id`) USING BTREE,
                                       INDEX `idx_dom_res_domain_alive`(`domain_id`, `delete_flag`, `is_valid`, `app_id`, `resource_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

