                                INDEX `org_role_id`(`role_id`) USING BTREE,
                                INDEX `org_role_org_id`(`org_id`) USING BTREE,
                                INDEX `org_arch_com`(`org_id`, `arch_id`, `com_id`) USING BTREE,
                                INDEX `org_is_valid_del`(`is_valid`, `delete_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '角色用户关联表，组织的角色默认被组织内的人员继承，默认嵌套继承，需要有树搜索算法支持。' ROW_FORMAT = Dynamic;

