                                           INDEX `sub_type_id`(`subject_type_id`) USING BTREE,
                                           INDEX `sub_role_id`(`role_id`) USING BTREE,
                                           INDEX `sub_is_valid_del`(`is_valid`, `delete_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '角色主体类型关系表：个人（自然人）、企业、政府、默认注册用户即为自然人，不同的主体类型可以默认不同的角色，不同的角' ROW_FORMAT = Dynamic;

