-- ----------------------------
-- Table structure for wo_object_scope_bind
-- ----------------------------
DROP TABLE IF EXISTS `wo_object_scope_bind`;
CREATE TABLE `wo_object_scope_bind` (
    `id`              bigint(20) UNSIGNED NOT NULL,
    `entity_key`      varchar(128) NOT NULL,
