    PRIMARY KEY (`id`) USING BTREE,
    UNIQUE INDEX `uk_object_scope_bind`(`entity_key`, `dimension_code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '对象范围维绑定' ROW_FORMAT = Dynamic;



-- ----------------------------
-- Table structure for wo_region_redirect
-- ----------------------------
DROP TABLE IF EXISTS `wo_region_redirect`;
CREATE TABLE `wo_region_redirect` (
    `id`              bigint(20) UNSIGNED NOT NULL,
    `from_code`       varchar(12)  NOT NULL COMMENT '失效/旧国标码',
    `to_code`         varchar(12)  NOT NULL COMMENT '现行国标码',
    `redirect_type`   varchar(32)  NOT NULL DEFAULT 'MERGE' COMMENT 'MERGE/RENAME/SPLIT 等',
    `effective_at`    datetime NULL DEFAULT NULL,
    `create_time`     datetime NULL DEFAULT NULL,
    `delete_flag`     varchar(10)  NOT NULL DEFAULT 'normal',
    `is_valid`        char(1)      NOT NULL DEFAULT '1',
    PRIMARY KEY (`id`) USING BTREE,
    UNIQUE INDEX `uk_region_redirect_from`(`from_code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '行政区划撤并映射' ROW_FORMAT = Dynamic;


DROP TABLE IF EXISTS `wo_role_data_policy_overlay`;
CREATE TABLE `wo_role_data_policy_overlay`  (
  `id` bigint(20) UNSIGNED NOT NULL,
  `role_id` bigint(20) UNSIGNED NOT NULL,
  `com_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `domain_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `data_policy` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `create_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT NULL,
  `create_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `update_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `update_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `delete_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'normal',
  `is_valid` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1',
  `versions` int(10) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_role_policy_overlay`(`role_id`, `com_id`, `domain_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;



