INSERT INTO `k_pubs` VALUES (279439799488266251, '<p>信息的详情页，支持富文本编辑，你可以在这里加入信息简介和多媒体图文，支持带格式的图文信息。</p>\n<p><img src=\"http://localhost:8000/store/2023/04/28003820karQeT8V.jpg\" width=\"447\" height=\"480\" /></p>\n<p>2023-04-28</p>', '示例信息', '免费发布信息可以发布各种便民信息，分享你的闲置物品，秀出你的日常心得，购物体验，各种分享。', 'publish', NULL, NULL, 'simple-info', 0, NULL, 'info', 1533544727530094592, 0, NULL, 0, 0, 0, 40, NULL, NULL, 1, '2023-04-27 21:11:50', '127.0.0.1', 1, '2023-05-05 22:30:16', '127.0.0.1', 'deleted', 1);
