INSERT INTO `k_pubs` VALUES (279496821072117767, '<p>这是信息的详情，描述信息的主题和出售的商品，要图文并茂，记得留下你的联系方式，最好同城自提奥。</p>\n<p><img src=\"http://localhost:8000/store/2023/05/05222945CSqCG8aA.jpg\" width=\"395\" height=\"425\" /></p>\n<p>一个真实的图，胜过千言万语，此处省略五百字。</p>\n<p>联系方式：地球村五里屯，老子徒弟张天封。</p>\n<p>要求：地球村同城自提，非诚勿扰。</p>', '这是信息的标题可以写一个重点突出简明易懂', NULL, 'publish', NULL, NULL, 'bieming1', 0, NULL, 'info', 1533544727530094592, 0, NULL, 0, 0, 0, NULL, NULL, NULL, 1, '2023-04-28 00:58:25', '127.0.0.1', 1, '2023-05-05 22:29:59', '127.0.0.1', 'deleted', 1);
INSERT INTO `k_pubs` VALUES (279497240485740546, '<p><strong>通过信息你可以了解到你寻找的事物在哪里。</strong></p>\n<p>这是内容区域。</p>\n<p>可以编辑多媒体内容。</p>\n<p>&nbsp;</p>', '信息中人们生产生活中不可或缺的行动指南', NULL, 'publish', NULL, NULL, 'test', 0, NULL, 'info', 1533544727530094592, 0, NULL, 0, 0, 0, 40, NULL, NULL, 1, '2023-04-28 01:00:05', '127.0.0.1', 1, '2023-05-02 00:04:28', '127.0.0.1', 'deleted', 1);
